column26:
=ifs(
C3="","",
Y3,"Certified OK",
countif(C:C,"="&C3)>1,"already registered / duplicate name! see "&join(" ",filter(Registry_ID,Registry_Construct_name=C3,Registry_ID<>B3)),
regexmatch(C3,"^[od]"),
if(W3<>"",
  if(W3="no","oID/dID should only need to be registered if GG donor?",
  let(cats,iferror(filter({AB$2:AG$2},{AB3:AG3}=""),FALSE),if(cats=FALSE,"✓ No registration errors found","enter "&join("; ",cats)&"!"))),"Indicate GG donor?"),

true,
if(and(L3="no",settings_RegistryWarnIfNotpABC123),if(regexmatch(C3,"^p[A-Z]{3}\d{3}$"),"","Invalid construct name?"&char(10)),"")&
let(
main_headers,{C$2,H$2,I$2,K$2,L$2,N$2,O$2,R$2,S$2,U$2,W$2,X$2},
main_entries,{C3,H3,I3,K3,L3,N3,O3,R3,S3,U3,W3,X3},
donor_additional_headers,{AB$2:AG$2,AK$2},
donor_additional_entries,{AB3:AG3,AK3},
let(output,join(", ",
iferror(filter(main_headers,main_entries=""),"■"),
if(W3="no","□",iferror(filter(donor_additional_headers,donor_additional_entries=""),"□"))
),
if(and(regexmatch(output,"■"),regexmatch(output,"□")),"✓ No registration errors found","Missing entries: "&char(10)&substitute(substitute(output,"■,",""),"□",""))
))
)
